t("Ghost Walk - Return", "Ghost Caminar - Return", "talent name")
t("Return to the location you used Ghost Walk from.", "Volver a la ubicación desde la que usaste Ghost Walk.", "tformat")
t("Spectral Sight", "Spectral Vision", "talent name")
